<?php
require_once __DIR__ . '/_bootstrap.php'; customerPostCsrf();$error='';$placed=null;
$items=customerRows("SELECT ci.product_id,ci.quantity,p.name,p.retail_price,(ci.quantity*p.retail_price) subtotal FROM cart_items ci JOIN products p ON p.id=ci.product_id WHERE ci.user_id=?",[$customerId]);$total=array_sum(array_map(fn($i)=>(float)$i['subtotal'],$items));
if($_SERVER['REQUEST_METHOD']==='POST'&&$items){$address=trim((string)($_POST['shipping_address']??''));$payment=$_POST['payment_method']??'cash_on_delivery';if($address==='')$error='A delivery address is required.';else{$s=customerQuery("INSERT INTO orders (user_id,total_amount,status,payment_method,shipping_address) VALUES (?,?,?,?,?)",[$customerId,$total,'pending',$payment,$address]);if($s){$placed=(int)$GLOBALS['db']->lastInsertId();foreach($items as $i)customerQuery('INSERT INTO order_items (order_id,product_id,quantity,unit_price) VALUES (?,?,?,?)',[$placed,$i['product_id'],$i['quantity'],$i['retail_price']]);customerQuery('DELETE FROM cart_items WHERE user_id=?',[$customerId]);}}}
customerPageStart('Checkout','');?><div class="cw-title"><div><h1>Secure checkout</h1><p>Confirm your delivery and payment details.</p></div></div><?php if($placed):?><div class="cw-alert">Order placed successfully. <a href="order-details.php?id=<?=$placed?>">View order →</a></div><?php elseif($error):?><div class="cw-alert error"><?=e($error)?></div><?php elseif(!$items):?><div class="cw-empty">Your cart is empty. <a href="cart.php">Return to cart →</a></div><?php else:?><div class="cw-grid cw-grid-2"><form class="cw-card cw-form" method="post"><?=csrfField()?><label>Delivery address<textarea name="shipping_address" required placeholder="Street, city, region"></textarea></label><label>Payment method<select name="payment_method"><option value="cash_on_delivery">Cash on delivery</option><option value="mtn_mobile_money">MTN Mobile Money</option><option value="orange_money">Orange Money</option></select></label><button class="cw-btn gold" type="submit">Place order · <?=e(formatPrice($total))?></button></form><section class="cw-card"><h2>Order summary</h2><?php foreach($items as $i):?><p><?=e($i['name'])?> × <?= (int)$i['quantity']?><strong style="float:right"><?=e(formatPrice($i['subtotal']))?></strong></p><?php endforeach;?></section></div><?php endif;?><?php customerPageEnd();?>